extracted_python_code:
result = Transactions.WHERE(
    (transaction_type == 'buy') & (DATEDIFF("days", date_time, 'now') <= 10)
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(name="ticker_groups", by=(ticker_symbol)).CALCULATE(
    ticker_symbol=ticker_symbol,
    num_buy_transactions=COUNT(Transactions)
).TOP_K(2, by=num_buy_transactions.DESC())

customers_for_ar = Customers.WHERE(
    (YEAR(join_date) == 2022) & (HAS(transactions_made) == 1)
).CALCULATE(
    country=country,
    is_active=(status == 'active')
)

activity_ratio_by_country = customers_for_ar.PARTITION(name="country_group", by=(country)).CALCULATE(
    country=country,
    AR=(SUM(Customers.is_active) / COUNT(Customers)) * 100.0
)

result = Broker.CALCULATE(
    customer_count=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

result = Transactions.WHERE(
    (date_time >= "2023-01-01") & (date_time < "2023-04-01")
).PARTITION(
    name="type_groups", by=(transaction_type)
).CALCULATE(
    transaction_type=transaction_type,
    num_distinct_customers=NDISTINCT(Transactions.customer_id),
    avg_shares=AVG(Transactions.shares)
).TOP_K(3, by=num_distinct_customers.DESC())

distinct_ticker_ids = DailyPrices.WHERE(date >= "2023-04-01").PARTITION(name="distinct_tickers", by=(ticker_id)).CALCULATE(
    ticker_id=ticker_id
)

top_countries_by_transaction_amount = Transactions.WHERE(
    DATEDIFF("days", date_time, DATETIME('now')) <= 30
).CALCULATE(
    country=customer.country,
    amount=amount
).PARTITION(
    name="country_groups", 
    by=country
).CALCULATE(
    country_name=country,
    number_of_transactions=COUNT(Transactions),
    total_transaction_amount=SUM(Transactions.amount)
).TOP_K(5, by=total_transaction_amount.DESC())

recent_customers_transactions = Broker.CALCULATE(
    num_transactions=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, DATETIME('now')) <= 70
        ).transactions_made
    )
)

monthly_average_price = Transactions.WHERE(
    (status == 'success') &
    (YEAR(date_time) == 2023) &
    ISIN(MONTH(date_time), (1, 2, 3))
).CALCULATE(
    year_month=JOIN_STRINGS("-", YEAR(date_time), LPAD(MONTH(date_time), 2, "0"))
).PARTITION(
    name="monthly_transactions", by=(year_month)
).CALCULATE(
    month=year_month,
    average_transaction_price=AVG(Transactions.price)
).ORDER_BY(month.ASC())

sales_by_model = Cars.WHERE(
    LIKE(UPPER(vin_number), '%M5%')
).PARTITION(
    name="car_models", by=(make, model)
).CALCULATE(
    make=make,
    model=model,
    num_sales=COUNT(Cars.sale_records)
)

highest_sales_by_model = Cars.WHERE(
    (HAS(sale_records) == 1) &
    (inventory_snapshots.WHERE(RANKING(by=snapshot_date.DESC(), per="Cars", allow_ties=True) == 1).SINGULAR().is_in_inventory == False)
).PARTITION(
    name="car_models", by=(make, model)
).CALCULATE(
    make=make,
    model=model,
    highest_sale_price=MAX(Cars.sale_records.sale_price)
).ORDER_BY(highest_sale_price.DESC())

result = Dealership.CALCULATE(
    avg_days_to_payment=ROUND(
        AVG(
            PaymentsReceived.CALCULATE(
                days_diff=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ),
        2
    )
)

gpm_for_2023 = Dealership.CALCULATE(
    total_revenue_2023=SUM(Sales.WHERE(YEAR(sale_date) == 2023).sale_price),
    total_cost_2023=SUM(Sales.WHERE(YEAR(sale_date) == 2023).car.cost)
).CALCULATE(
    gpm=(total_revenue_2023 - total_cost_2023) / total_cost_2023 * 100.0
)

highest_priced_car = Sales.WHERE(
    HAS(
        car.inventory_snapshots.WHERE(
            (snapshot_date == sale_date) & (is_in_inventory == False)
        )
    ) == 1
).TOP_K(
    1, by=sale_price.DESC()
).CALCULATE(
    make=car.make,
    model=car.model,
    sale_price=sale_price
)

result = Dealership.CALCULATE(
    TSC=COUNT(Sales.WHERE(
        (DATEDIFF("days", sale_date, DATETIME('now')) < 7) & (DATEDIFF("days", sale_date, DATETIME('now')) >= 0)
    ))
)

result = Customers.WHERE(HAS(car_purchases) == 1).CALCULATE(
    customer_id=_id
)

cash_salespersons = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(payment_method == 'Cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

result = Salespersons.CALCULATE(
    first_name=first_name,
    last_name=last_name,
    total_sales_count=COUNT(sales_made.WHERE(DATEDIFF("days", sale_date, DATETIME('now')) <= 30)),
    total_revenue_amount=SUM(sales_made.WHERE(DATEDIFF("days", sale_date, DATETIME('now')) <= 30).sale_price)
).WHERE(
    total_sales_count > 0
).TOP_K(
    5, by=total_sales_count.DESC()
)

result = Dealership.CALCULATE(
    num_payments=COUNT(
        PaymentsMade.WHERE(
            (vendor_name == 'Utility Company') & 
            ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday'))
        )
    )
)

result = Sales.WHERE(
    YEAR(sale_date) == 2023
).CALCULATE(
    customer_state=customer.state,
    quarter_start_date=IFF(
        MONTH(sale_date) <= 3, "2023-01-01",
        IFF(
            MONTH(sale_date) <= 6, "2023-04-01",
            IFF(
                MONTH(sale_date) <= 9, "2023-07-01", 
                "2023-10-01"
            )
        )
    )
).PARTITION(
    name="state_quarter_groups", 
    by=("customer_state", "quarter_start_date")
).CALCULATE(
    state=customer_state,
    quarter=quarter_start_date,
    total_sales=SUM(Sales.sale_price)
)

cars_in_latest_snapshot = InventorySnapshots.WHERE(
    (YEAR(snapshot_date) == 2023) & (MONTH(snapshot_date) == 3)
).WHERE(
    (RANKING(by=snapshot_date.DESC(), allow_ties=True) == 1) & (is_in_inventory == True)
).car.CALCULATE(
    _id=_id,
    make=make,
    model=model,
    year=year
)

gmail_or_yahoo_patients_count = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            ENDSWITH(email, "@gmail.com") | ENDSWITH(email, "@yahoo.com")
        )
    )
)

filtered_patients_count = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (diagnosis.diag_name == 'Psoriasis vulgaris') & (drug.drug_type == 'biologic')
                )
            ) == 1
        )
    )
)

alice_treatment_count = Patients.WHERE(first_name == "Alice").CALCULATE(
    num_treatments=COUNT(treatments_received.WHERE(
        (start_dt >= DATETIME('now', 'start of month', '-6 months')) & 
        (start_dt < DATETIME('now', 'start of month'))
    ))
)

average_patient_weight = DermTreatment.CALCULATE(
    average_weight=AVG(Drugs.WHERE(drug_name == 'Drugalin').treatments_used_in.patient.weight_kg)
)

caw_male_patients = DermTreatment.CALCULATE(
    caw=AVG(Patients.WHERE(gender == 'Male').weight_kg)
)

result = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE((gender == 'F') & (ins_type == 'private')))
)

top_drug_by_adverse_events = Drugs.CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name,
    num_adverse_events=COUNT(
        treatments_used_in.adverse_events.WHERE(
            (YEAR(reported_dt) == YEAR(treatment.start_dt)) &
            (MONTH(reported_dt) == MONTH(treatment.start_dt))
        )
    )
).TOP_K(1, by=num_adverse_events.DESC())

result = Drugs.WHERE(drug_type == 'biologic').treatments_used_in.doctor.PARTITION(name="states", by=loc_state).CALCULATE(
    state=loc_state
).ORDER_BY(loc_state.ASC())

top_diagnoses_by_itch_score = Diagnoses.WHERE(
    HAS(treatments_for.outcome_records) == 1
).CALCULATE(
    diag_name=diag_name,
    max_itch_score=MAX(treatments_for.outcome_records.day100_itch_vas),
    num_patients=NDISTINCT(treatments_for.patient.patient_id)
).TOP_K(
    3,
    by=(max_itch_score.DESC(), num_patients.DESC())
)

top_3_specialties_by_drug_amount = Treatments.WHERE(
    start_dt >= DATETIME('now', '-6 months')
).CALCULATE(
    speciality=doctor.speciality
).PARTITION(
    name="specialty_group", by=(speciality)
).CALCULATE(
    speciality=speciality,
    num_treatments=COUNT(Treatments),
    total_drug_amount=SUM(Treatments.tot_drug_amt)
).TOP_K(3, by=total_drug_amount.DESC())

psoriasis_treatments_count = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Treatments.WHERE(
            (LIKE(LOWER(diagnosis.diag_name), '%psoriasis%')) &
            (HAS(drug.fda_appr_dt) == 1) &
            (end_dt >= DATETIME('now', '-6 months')) &
            (end_dt <= DATETIME('now'))
        )
    )
)

result = DermTreatment.CALCULATE(
    avg_patient_age=ROUND(AVG(
        Patients.WHERE(
            (gender == 'male') & (ins_type == 'private')
        ).CALCULATE(
            age=DATEDIFF("years", date_of_birth, DATETIME('now'))
        ).age
    ), 0)
)

lub_per_user = Users.CALCULATE(
    user_id=uid,
    latest_user_balance=balances.WHERE(
        RANKING(by=updated_at.DESC(), per="Users") == 1
    ).SINGULAR().balance
)

tuc_past_month = Ewallet.CALCULATE(
    TUC=COUNT(UserSessions.WHERE(session_start_ts >= DATETIME('now', '-1 month')))
)

users_with_unread_promos = Users.WHERE(
    (LOWER(country) == 'us') &
    (HAS(notifications.WHERE((notification_type == 'promotional') & (status == 'unread'))) == 1)
).CALCULATE(
    username=username,
    total_unread_promotional_notifications=COUNT(
        notifications.WHERE((notification_type == 'promotional') & (status == 'unread'))
    )
)

distinct_merchant_ids = Transactions.WHERE(receiver_type == '1').PARTITION(name="merchants", by=(receiver_id)).CALCULATE(
    merchant_id=receiver_id
)

distinct_user_ids_with_transaction_notifications = Notifications.WHERE(notification_type == 'transaction').PARTITION(name="distinct_users", by=(user_id)).CALCULATE(
    user_id=user_id
)

median_balance_for_active_retail_merchants = Ewallet.CALCULATE(
    median_merchant_balance=MEDIAN(
        Merchants.WHERE(
            (status == 'active') & CONTAINS(LOWER(category), 'retail')
        ).balances.WHERE(
            RANKING(by=updated_at.DESC(), per="Merchants") == 1
        ).balance
    )
)

avg_limits_for_earliest_snapshot = Ewallet.CALCULATE(
    earliest_date_2023=MIN(UserSettingSnapshots.WHERE(YEAR(snapshot_date) == 2023).snapshot_date)
).CALCULATE(
    avg_daily_limit=AVG(UserSettingSnapshots.WHERE(snapshot_date == earliest_date_2023).tx_limit_daily),
    avg_monthly_limit=AVG(UserSettingSnapshots.WHERE(snapshot_date == earliest_date_2023).tx_limit_monthly)
)

result = UserSessions.PARTITION(name="sessions_by_device", by=(device_type)).CALCULATE(
    device_type=device_type,
    avg_session_duration_seconds=AVG(
        DATEDIFF("seconds", sessions_by_device.session_start_ts, sessions_by_device.session_end_ts)
    )
)
